        return [0]

    a = a % m

    # Factorize m into prime powers
    factors = []
    d = 2
    temp = m
    while d * d <= temp:
        if temp % d == 0:
            e = 0
            while temp % d == 0:
                e += 1
                temp //= d
            factors.append((d, e))
        d += 1
    if temp > 1:
        factors.append((temp, 1))

