    return _solve_mod_odd_prime_power(a, p, e)


def _solve_mod_2pow(a: int, e: int) -> list[int]:
    if e == 1:
        return [a % 2]
    if e == 2:
        if a % 4 == 0:
            return [0, 2]
        if a % 4 == 1:
            return [1, 3]
        return []

    # e >= 3
    if a & 1:  # odd a
        if a % 8 != 1:
            return []
        x = 1
        for k in range(3, e):
            diff = (a - x * x) >> k
            t = diff & 1
            x += t << (k - 1)
        n = 1 << e
        half = 1 << (e - 1)
        return sorted({x % n, (n - x) % n, (x + half) % n, (n - x + half) % n})

    # even a
    if a == 0:
        k = e
    else:
        k = 0
        temp = a
        while temp % 2 == 0:
            k += 1
            temp //= 2

    if k & 1:
        return []
    if k >= e:
        limit = 1 << ((e + 1) // 2)
        return list(range(0, 1 << e, limit))

    j = k // 2
    rem_e = e - k
    u = a >> k
    roots_y = _solve_mod_2pow(u, rem_e)
    if not roots_y:
        return []

    shift = 1 << j
    n = 1 << e
    res = []
    for y0 in roots_y:
        for t in range(1 << j):
            y = y0 + t * (1 << rem_e)
            res.append((y * shift) % n)
    return sorted(set(res))


def _solve_mod_odd_prime_power(a: int, p: int, e: int) -> list[int]:
