            return []
        if k >= e:
            limit = p ** ((e + 1) // 2)
            return list(range(0, n, limit))

        j = k // 2
        rem_e = e - k
        u = temp
        roots_y = _solve_mod_odd_prime_power(u, p, rem_e)
        if not roots_y:
            return []

        shift = p ** j
        res = []
        for y0 in roots_y:
            for t in range(p ** j):
                y = y0 + t * (p ** rem_e)
                res.append((y * shift) % n)
