from fractions import Fraction
import math

def billiard(W, H, x, y, vx, vy, t, e=1):
    # Input validation
    if not isinstance(W, int) or not isinstance(H, int) or W <= 0 or H <= 0:
        raise ValueError("W, H must be positive integers")
    if not isinstance(x, (int, Fraction)) or not isinstance(y, (int, Fraction)):
        raise ValueError("x, y must be int or Fraction")
    if not (0 < x < W) or not (0 < y < H):
        raise ValueError("Start position must be strictly inside")
    if not isinstance(vx, int) or not isinstance(vy, int):
        raise ValueError("vx, vy must be integers")
    if not isinstance(t, (int, Fraction)) or t < 0:
        raise ValueError("t must be non-negative int or Fraction")
    if not isinstance(e, (int, Fraction)) or not (0 < e <= 1):
        raise ValueError("e must be int or Fraction with 0 < e <= 1")

    def solve_1d(L, p0, v0, t, e):
        if v0 == 0:
            return p0, 0, 0

        abs_v0 = abs(v0)

        if e == 1:
            # e = 1: periodic motion, O(1)
            X_unfolded = p0 + v0 * t

            if v0 > 0:
                n_hits = X_unfolded // L
            else:
                # v0 < 0: hits at 0, -L, -2L, ...
                # Count k*L in [X_unfolded, p0), k <= 0
                ceil_X_L = -(-X_unfolded // L)
                n_hits = 1 - ceil_X_L
                if n_hits < 0:
                    n_hits = 0

            rem = X_unfolded % (2 * L)
            if rem > L:
                p_final = 2 * L - rem
            else:
                p_final = rem

            v_final = v0 * ((-1) ** n_hits)
            return p_final, v_final, n_hits

        else:
            # e < 1: exact rational arithmetic
            if v0 > 0:
                t0 = Fraction(L - p0, abs_v0)
            else:
                t0 = Fraction(p0, abs_v0)

            if t < t0:
                return p0 + v0 * t, v0, 0

            # Time of n-th hit (n >= 1):
            # T_n = t0 + (L/|v0|) * ((1/e)^(n-1) - 1) / (1 - e)
            rhs_val = 1 + (t - t0) * (1 - e) * abs_v0 / L

            if rhs_val <= 1:
                n_est = 1
            else:
                # Estimate using floats; exact adjustment follows
                val = 1 + math.log(float(rhs_val)) / (-math.log(float(e)))
                n_est = math.floor(val)

            inv_e = Fraction(1, 1) / e
            one_minus_e = 1 - e
            speed_factor = Fraction(L, abs_v0)

            def get_T(n):
                term = (inv_e ** (n - 1) - 1) / one_minus_e
                return t0 + speed_factor * term

            if n_est < 1:
                n_est = 1

            T_n = get_T(n_est)
            if T_n > t:
                while n_est > 1 and get_T(n_est) > t:
                    n_est -= 1
            else:
                while get_T(n_est + 1) <= t:
                    n_est += 1

            n_hits = n_est

            # Velocity after n_hits
            v_final = v0 * ((-1) ** n_hits) * (e ** n_hits)

            # Wall at the n_hits-th hit
            if v0 > 0:
                wall_at_n = L if (n_hits % 2 == 1) else 0
            else:
                wall_at_n = 0 if (n_hits % 2 == 1) else L

            # Remaining travel after the last hit
            dt = t - T_n
            dist = abs(v_final) * dt
            sign_after_n = 1 if v_final > 0 else -1
            p_final = wall_at_n + sign_after_n * dist

            return p_final, v_final, n_hits

    X, VX, hits_x = solve_1d(W, x, vx, t, e)
    Y, VY, hits_y = solve_1d(H, y, vy, t, e)

    return (X, Y, VX, VY, hits_x, hits_y)

